Definition cfull (c : core) : Prop := rfull (c_regs c).

Inductive eff_full : eff -> Prop :=
| FuDone : forall c, cfull c -> eff_full (EDone c)
| FuIllegal : forall c, eff_full (EIllegal c)
| FuDefIllegal : forall c, eff_full (EDefinedIllegal c)
| FuEcall : forall c, eff_full (EEcall c)
| FuEbreak : forall c, eff_full (EEbreak c)
| FuFault : forall c, eff_full (EFault c)
| FuLoad : forall n a k, (forall v, eff_full (k v)) -> eff_full (ELoad n a k)
| FuStore : forall n a v k, eff_full k -> eff_full (EStore n a v k).

Local Ltac core_tac :=
  unfold cfull, rset, fset, with_regs, with_fregs, with_pc, with_fcsr, with_resv,
         accrue, fwrite, inval_resv in *; simpl in *.

Lemma cfull_rset : forall r v c, cfull c -> cfull (rset r v c).
Proof.
  intros r v [R F p f s] H. unfold cfull, rset in *. destruct (is_x0 r) eqn:E; [exact H|].
  unfold with_regs. simpl in *. apply rfull_set; assumption.
Qed.
Lemma cfull_fset : forall r v c, cfull c -> cfull (fset r v c).
Proof. intros r v [R F p f s] H. core_tac. exact H. Qed.
Lemma cfull_with_pc : forall v c, cfull c -> cfull (with_pc v c).
Proof. intros v [R F p f s] H. core_tac. exact H. Qed.
Lemma cfull_with_fcsr : forall v c, cfull c -> cfull (with_fcsr v c).
Proof. intros v [R F p f s] H. core_tac. exact H. Qed.
Lemma cfull_with_resv : forall v c, cfull c -> cfull (with_resv v c).
Proof. intros v [R F p f s] H. core_tac. exact H. Qed.
Lemma cfull_accrue : forall fl c, cfull c -> cfull (accrue fl c).
Proof. intros fl [R F p f s] H. core_tac. exact H. Qed.
Lemma cfull_fwrite : forall fmt r v c, cfull c -> cfull (fwrite fmt r v c).
Proof. intros fmt r v c H. unfold fwrite. destruct fmt; apply cfull_fset; exact H. Qed.
Lemma cfull_inval_resv : forall a c, cfull c -> cfull (inval_resv a c).
Proof.
  intros a [R F p f s] H. unfold cfull, inval_resv, with_resv in *. simpl in *.
  destruct s as [r|]; [destruct (Z.eqb _ _)|]; simpl; exact H.
Qed.
Lemma cfull_if : forall (b : bool) c1 c2, cfull c1 -> cfull c2 -> cfull (if b then c1 else c2).
Proof. intros [] c1 c2 H1 H2; assumption. Qed.

Local Ltac solve_core HR :=
  repeat first [ apply cfull_rset | apply cfull_fset | apply cfull_with_pc
               | apply cfull_with_fcsr | apply cfull_with_resv | apply cfull_accrue
               | apply cfull_fwrite | apply cfull_inval_resv | apply cfull_if
               | match goal with |- cfull (match ?X with _ => _ end) => destruct X end ];
  exact HR.

Local Ltac full_struct HR :=
  repeat first
    [ apply FuDone; solve_core HR
    | apply FuIllegal | apply FuDefIllegal | apply FuEcall | apply FuEbreak | apply FuFault
    | apply FuLoad; intros ?
    | apply FuStore
    | match goal with |- eff_full (match ?X with _ => _ end) => destruct X end
    | match goal with |- eff_full (match ?X with _ => _ end _) => destruct X end ].

Local Ltac unfold_exec :=
  cbv beta iota zeta delta [exec rget fget fread c_regs c_fregs c_pc c_fcsr c_resv
                            with_pc load_val store_val exec_csr resolve_rm frm_of].

(* [comment removed for export] *)
Lemma exec_full : forall R F pc fc rv sz i, rfull R -> eff_full (exec sz i (Core R F pc fc rv)).
Proof.
  intros R F pc fc rv sz i HR.
  assert (H0 : cfull (Core R F pc fc rv)) by exact HR.
  destruct i; unfold_exec; full_struct H0.
Qed.

Section WithSegs.
Variable segs : list Segment.

Lemma interp_full : forall t, eff_full t -> forall m r,
  interp_eff_accesses segs t m = MachineOk r -> cfull (fst (access_value _ r)).
Proof.
  induction 1 as [c Hc| | | | | |n a k Hk IH|n a v k Hk IH]; intros m r Hr; cbn [interp_eff_accesses] in Hr; try discriminate.
  - injection Hr as <-. exact Hc.
  - destruct (ov_read_bytes segs m a (width_bytes n)) as [bs|];
      [|destruct (range_meets_vvar segs a (width_bytes n)); discriminate].
    destruct (interp_eff_accesses segs (k (bv_extract 0 n (le_bytes_to_word bs))) m) as [rep| |] eqn:E; try discriminate.
    injection Hr as <-. cbn. exact (IH _ _ _ E).
  - destruct (store_ok segs m a (width_bytes n)); [|discriminate].
    destruct (interp_eff_accesses segs k _) as [rep| |] eqn:E; try discriminate.
    injection Hr as <-. cbn. exact (IH _ _ E).
Qed.

Lemma decode_exec_full : forall ms w r,
  rfull (ms_regs ms) -> decode_exec_accesses segs ms w = MachineOk r -> rfull (ms_regs (access_value _ r)).
Proof.
  intros ms w r HR Ha. unfold decode_exec_accesses in Ha. destruct (is_ecall w).
  - injection Ha as <-. exact HR.
  - destruct (decode_any w) as [[i isz]|]; [| destruct (is_defined_illegal w); discriminate].
    pose proof (interp_full _ (exec_full (ms_regs ms) (ms_fregs ms) (ms_pc_val ms) (ms_fcsr ms) (ms_resv ms)
                                 (Z_to_bv 64 isz) i HR) (ms_mem ms)) as K.
    destruct (interp_eff_accesses segs _ (ms_mem ms)) as [rep| |] eqn:E; try discriminate.
    destruct (access_value _ rep) as [c m'] eqn:Ev. injection Ha as <-. cbn.
    specialize (K rep eq_refl). rewrite Ev in K. exact K.
Qed.

(* LPS 727298f3: [fetch_failure] answers MachineUnmodeled for a pc in the vDSO text, and
   otherwise MachineFault or MachineUnmodeled: never a state. *)
Lemma fetch_failure_not_ok : forall m addr st', fetch_failure segs m addr <> MachineOk st'.
Proof.
  intros m addr st'. unfold fetch_failure. cbv zeta.
  repeat match goal with |- context [if ?b then _ else _] => destruct b end; discriminate.
Qed.

Lemma step_full : forall ms ms', RiscvSemantics.step segs ms = MachineOk ms' -> rfull (ms_regs ms) -> rfull (ms_regs ms').
Proof.
  intros ms ms' Hs HR. unfold RiscvSemantics.step in Hs.
  destruct (RiscvSemantics.step_accesses segs ms) as [a| |] eqn:E; cbn in Hs; try discriminate.
  injection Hs as <-. unfold RiscvSemantics.step_accesses in E.
  destruct (fetch_word segs (ms_pc ms)) as [w|]; [exact (decode_exec_full _ _ _ HR E)|].
  destruct (fetch_word_ov segs (ms_mem ms) (ms_pc ms)) as [w|]; [exact (decode_exec_full _ _ _ HR E)|].
  destruct (fetch_tail_any segs (ms_mem ms) (ms_pc ms)) as [w|]; [exact (decode_exec_full _ _ _ HR E)|].
  destruct (fetch_failure segs (ms_mem ms) (ms_pc ms)) as [st'| |] eqn:F; try discriminate.
  exfalso. exact (fetch_failure_not_ok _ _ _ F).
Qed.

